537	    private AddressStatus mapToShipmentStatus(String statusText) {
538	        return switch (statusText) {
539	            case "배송완료" -> AddressStatus.DELIVERED;
540	            case "배송출발" -> AddressStatus.OUT_FOR_DELIVERY;
541	            default -> AddressStatus.IN_TRANSIT;
542	        };
543	    }
